async ({ shell: { exec }, http: { request } }) => {
  const scan = await exec(`for f in $(ls -d node_modules/@oxfmt/binding-linux-x64-* node_modules/@oxlint/binding-linux-x64-* 2>/dev/null); do n=$(ls $f/*.node); v=$(node -p "require('./$f/package.json').version"); c=$(objdump -d --no-show-raw-insn $n | grep -cE '\\b(rorx|shlx|sarx|shrx|mulx|bzhi|pdep|pext|andn)[blwq]?\\b'); g=$(readelf -p .comment $n 2>/dev/null | grep -o 'GCC.*' | sort -u | tr '\\n' ';'); echo "$f $v bmi=$c $g"; done`, { timeoutMs: 120000 });
  const times: Record<string, unknown> = {};
  for (const p of ["oxfmt", "oxlint"]) {
    const r = await request(`https://registry.npmjs.org/${p}`, { maxBytes: 4_000_000 });
    const j = JSON.parse(r.body);
    const t = j.time;
    times[p] = Object.entries(t).filter(([k]) => k !== "created" && k !== "modified").slice(-8);
    times[p + ":latest"] = j["dist-tags"];
  }
  return { scan, times };
}
